import numpy as np

def solve(inp):
    g=[r[:] for r in inp]
    H,W=len(g),len(g[0])
    # immovable cells = 2s; shapes = connected components of other nonzero
    seen=[[False]*W for _ in range(H)]
    shapes=[]
    obstacles=[[g[r][c]==2 for c in range(W)] for r in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c] and g[r][c]!=2 and not seen[r][c]:
                col=g[r][c]; stack=[(r,c)]; cells=[]; seen[r][c]=True
                while stack:
                    rr,cc=stack.pop(); cells.append((rr,cc))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr,cc+dc
                        if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and g[nr][nc]==col and g[nr][nc]!=2:
                            seen[nr][nc]=True; stack.append((nr,nc))
                shapes.append(cells)
    # clear shapes from grid
    for cells in shapes:
        for r,c in cells: g[r][c]=0
    # gravity: rounds where every movable shape drops 1
    changed=True
    while changed:
        changed=False
        occupied=set()
        for cells in shapes: occupied.update(cells)
        for cells in shapes:
            if all(r+1<H and (r+1,c) not in occupied and not obstacles[r+1][c] for r,c in cells):
                occupied.difference_update(cells)
                for i,(r,c) in enumerate(cells): cells[i]=(r+1,c)
                occupied.update(cells)
                changed=True
    for cells in shapes:
        for r,c in cells: g[r][c]=g[r][c] or 0
    # need colors: store color per shape
    return g, shapes

